(46861, 'Psalms 37:3', 'Psalms', 37, 3, 'کړه توکل دې په څښتن کوه نېکي نو خپل وطن کې دې اوسېږه خوند د امن اخله', 'کره توکل دې په چشتن کوه نېکی نو خپل وطن کې دې اوسېزه خوند د امن اخله', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_37_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46862, 'Psalms 37:4', 'Psalms', 37, 4, 'لټوه ته خوشحالي دې په څښتن کې هغه به ستا د زړه ارزو کړي پوره', 'لتوه ته خوشحالی دې په چشتن کې هغه به ستا د زره ارزو کری پوره', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_37_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46863, 'Psalms 37:5', 'Psalms', 37, 5, 'خپله لاره دې ته وسپاره څښتن ته وکړه توکل په هغه باندې مرسته ستا به وکړي', 'خپله لاره دې ته وسپاره چشتن ته وکره توکل په هغه باندې مرسته ستا به وکری', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_37_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46864, 'Psalms 37:6', 'Psalms', 37, 6, 'کړي به سهار په څېر روښانه نېکي ستا وځلوي به دې انصاف غرمې د لمر په څېر', 'کری به سهار په چېر روشانه نېکی ستا وجلوی به دې انصاف غرمې د لمر په چېر', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_37_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46865, 'Psalms 37:7', 'Psalms', 37, 7, 'وکړه انتظار غلی څښتن په مخکې صبر شه اندېښنه مه کړه د هغه چا په هکله چې خوشبخت دی یا هغه چې دی کامیاب په خپلو بدو پلانو کې', 'وکره انتظار غلی چشتن په مخکې صبر شه اندېشنه مه کره د هغه چا په هکله چې خوشبخت دی یا هغه چې دی کامیاب په خپلو بدو پلانو کې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_37_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46866, 'Psalms 37:8', 'Psalms', 37, 8, 'مه په قهرېږه غوسه کېږه مه مه کړه اندېښنه ځکه بدۍ ته به دې بوځي اندېښنه', 'مه په قهرېزه غوسه کېزه مه مه کره اندېشنه جکه بدی ته به دې بوجی اندېشنه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_37_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46867, 'Psalms 37:9', 'Psalms', 37, 9, 'له منځه لاړ به شي ټول بدکاران خو څوک چې کاندي توکل په څښتن ځمکه به شي د هغوی', 'له منجه لار به شی تول بدکاران خو چوک چې کاندی توکل په چشتن جمکه به شی د هغوی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_37_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46868, 'Psalms 37:10', 'Psalms', 37, 10, 'ورک به په لږ وخت کې بدکاران شي نه به پیدا کیږي که هرڅومره یې لټون کوې', 'ورک به په لز وخت کې بدکاران شی نه به پیدا کیزی که هرچومره یې لتون کوې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_37_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46869, 'Psalms 37:11', 'Psalms', 37, 11, 'عاجزان خلک به د ځمکې وارثان شي د سوکالۍ او ارامۍ نه به خوندونه اخلي', 'عاجزان خلک به د جمکې وارثان شی د سوکالی او ارامی نه به خوندونه اخلی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_37_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
